declare(strict_types=1);session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../lib/session_login_admin.php';
function flashD(string $a,string $t,string $m):void{$_SESSION['hasil']=['alert'=>$a,'judul'=>$t,'pesan'=>$m];}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');try{
  if($action==='visibility'){$id=(int)($_POST['id']??0);$v=!empty($_POST['public_visible'])?1:0;$s=$conn->prepare("UPDATE layanan_digital SET public_visible=?,updated_at=NOW() WHERE id=? AND provider='DHRU'");$s->bind_param('ii',$v,$id);$s->execute();$s->close();}
  elseif($action==='save'){$id=(int)($_POST['id']??0);$sid=trim((string)($_POST['service_id']??''));$group=trim((string)($_POST['dhru_group']??'DHRU'));$name=trim((string)($_POST['layanan']??''));$cost=max(0,(float)($_POST['harga_api']??0));$sell=max(0,(float)($_POST['harga']??0));$status=($_POST['status']??'Normal')==='Normal'?'Normal':'Gangguan';$visible=!empty($_POST['public_visible'])?1:0;$note=trim((string)($_POST['catatan']??''));if($sid===''||$name==='')throw new RuntimeException('Service ID dan nama produk wajib diisi.');if($sell<=0)$sell=$cost;$profit=$sell-$cost;
   if($id>0){$s=$conn->prepare("UPDATE layanan_digital SET service_id=?,provider_id=?,operator=?,dhru_group=?,layanan=?,harga=?,harga_api=?,profit=?,status=?,tipe='Digital',catatan=?,public_visible=?,updated_at=NOW() WHERE id=? AND provider='DHRU'");$s->bind_param('ssss sdddssii',$sid,$sid,$group,$group,$name,$sell,$cost,$profit,$status,$note,$visible,$id);}
   else{$provider='DHRU';$s=$conn->prepare("INSERT INTO layanan_digital (service_id,provider_id,operator,dhru_group,layanan,harga,harga_api,profit,status,provider,tipe,catatan,public_visible,sort_order,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,'Digital',?,?,0,NOW())");$s->bind_param('ssss sdddsss i',$sid,$sid,$group,$group,$name,$sell,$cost,$profit,$status,$provider,$note,$visible);}
   $s->bind_param('ssss sdddssii',$sid,$sid,$group,$group,$name,$sell,$cost,$profit,$status,$note,$visible,$id);
   $s->execute();$s->close();flashD('success','Produk tersimpan','Produk DHRU berhasil disimpan.');
  }elseif($action==='bulk'){$ids=$_POST['ids']??[];$v=($_POST['mode']??'')==='show'?1:0;if(is_array($ids)&&$ids){$s=$conn->prepare("UPDATE layanan_digital SET public_visible=?,updated_at=NOW() WHERE id=? AND provider='DHRU'");foreach($ids as $id){$id=(int)$id;$s->bind_param('ii',$v,$id);$s->execute();}$s->close();}}
 }catch(Throwable $e){flashD('danger','Gagal',htmlspecialchars($e->getMessage()));}header('Location: dhru-products.php');exit;
}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare("SELECT * FROM layanan_digital WHERE id=? AND provider='DHRU' LIMIT 1");$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();$s->close();}$q=$conn->query("SELECT id,service_id,operator,dhru_group,layanan,harga,harga_api,profit,status,public_visible FROM layanan_digital WHERE provider='DHRU' ORDER BY operator ASC,sort_order ASC,id DESC");require_once __DIR__.'/../lib/header_admin.php';
?>
