s((string)($edit['catatan']??''))?>"></div><div class="col-md-2 form-group pt-4"><label><input type="checkbox" name="public_visible" value="1" <?=!empty($edit['public_visible'])?'checked':''?>> Publish reseller</label></div><div class="col-md-2 form-group pt-4"><button class="btn btn-primary btn-block">Simpan</button><?php if($edit):?><a class="btn btn-light btn-block" href="dhru-products">Batal</a><?php endif;?></div></div></form></div><form method="post"><input type="hidden" name="action" value="bulk"><div class="dh3-card dh3-table"><div class="d-flex justify-content-between mb-3"><h4>Catalog</h4><div><button class="btn btn-success btn-sm" name="mode" value="show">Publish</button> <button class="btn btn-warning btn-sm" name="mode" value="hide">Hide</button></div></div><table class="table table-hover"><thead><tr><th><input type="checkbox" onclick="document.querySelectorAll('.pick').forEach(x=>x.checked=this.checked)"></th><th>Produk</th><th>Group</th><th>Modal</th><th>Jual</th><th>Profit</th><th>Status</th><th>Publish</th><th></th></tr></thead><tbody><?php if($q):while($r=$q->fetch_assoc()):?><tr><td><input class="pick" type="checkbox" name="ids[]" value="<?=$r['id']?>"></td><td><b><?=htmlspecialchars($r['layanan'])?></b><br><small><?=htmlspecialchars($r['service_id'])?></small></td><td><?=htmlspecialchars((string)($r['dhru_group']?:$r['operator']))?></td><td>Rp <?=number_format((float)$r['harga_api'],0,',','.')?></td><td>Rp <?=number_format((float)$r['harga'],0,',','.')?></td><td>Rp <?=number_format((float)$r['profit'],0,',','.')?></td><td><?=htmlspecialchars($r['status'])?></td><td><span class="dh3-pill <?=!empty($r['public_visible'])?'bg-success text-white':'bg-light'?>"><?=!empty($r['public_visible'])?'ON':'OFF'?></span></td><td><a class="btn btn-sm btn-info" href="?edit=<?=$r['id']?>">Edit</a></td></tr><?php endwhile;endif;?></tbody></table></div></form></div>
